/**
 * Multi-line text entry (`design/components/textarea.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/textarea.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  agentFill,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  fitTextarea,
  useControlRef,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/textarea.module.css'

export type TextareaResize = NonNullable<TextareaProps['resize']>

export interface TextareaProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  /**
   * Names the field from a label elsewhere on the page, such as `SettingsRow`'s row label, which
   * is one label for a whole row rather than one per control.
   */
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Native passthrough, as in Input. For surfaces that have already moved the user, such as a
   * dialog's first field. Never use it to take focus when a page loads.
   */
  autoFocus?: boolean
  /**
   * Grows with its content. Opt-in, because a field that grows while typing moves everything
   * below it, and the form decides that, not the field. Implies `resize: 'none'`, because a box
   * that resizes itself and can also be dragged would have two owners for one height.
   */
  autosize?: boolean
  /**
   * The native `<textarea>`, like Input's `controlRef`, for an application binding that must
   * read or restore a caret or selection. Merged with the autosizer's ref, so both get the same
   * node, and `null` on unmount.
   */
  controlRef?: (element: HTMLTextAreaElement | null) => void
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  maxLength?: number
  name?: string
  /**
   * For touched validation, as in Input: apps mark a field dirty when focus leaves.
   */
  onBlur?: (event: FocusEvent) => void
  onChange?: (value: string, event: Event) => void
  /**
   * Native passthrough for IME composition end. `event.data` is the committed text.
   */
  onCompositionEnd?: (event: CompositionEvent) => void
  /**
   * Native passthrough for IME composition start. Composition events arrive as the platform
   * fires them, never suppressed and never repeated as a second change.
   */
  onCompositionStart?: (event: CompositionEvent) => void
  onFocus?: (event: FocusEvent) => void
  /**
   * Native passthrough. Fires when the caret or range moves, by keyboard or pointer.
   * `selectionStart`, `selectionEnd` and `selectionDirection` are on `event.currentTarget`. The
   * member never moves the selection itself.
   */
  onSelect?: (event: Event) => void
  placeholder?: string
  readOnly?: boolean
  /**
   * Never horizontal, because column width belongs to the layout, not the user.
   */
  resize?: 'vertical' | 'none'
  /**
   * The height, in line units.
   */
  rows?: number
  value?: string
}

/** Multi-line text entry. */
export default function Textarea(given: TextareaProps): JSX.Element {
  const props = mergeProps(
    {
      rows: 4,
      autosize: false,
      invalid: false,
      disabled: false,
      readOnly: false,
      autoFocus: false,
    } as Defaults<
      TextareaProps,
      'rows' | 'autosize' | 'invalid' | 'disabled' | 'readOnly' | 'autoFocus'
    >,
    claimSlot(given),
  )
  const draft = createCell(props.defaultValue ?? '')
  const control = useControlRef(() => props.controlRef)
  const resizing = createDerived(() => props.resize ?? (props.autosize ? 'none' : 'vertical'))
  const effect1 = () => {
    void (props.autosize && control.value && fitTextarea(control.value))
  }
  watchEffect(
    createMemo(() => [props.value, props.defaultValue, props.autosize]),
    effect1,
    true,
  )
  const effect2 = () => {
    void (props.autoFocus && control.value?.focus())
  }
  onMount(effect2)
  let release3: (() => void) | undefined
  const effect3 = () => {
    release3?.()
    const ran = agentMember({
      member: 'Textarea',
      element: () => control.value,
      state: () => ({
        value: props.value ?? draft.value,
        disabled: props.disabled,
        invalid: props.invalid,
        readonly: props.readOnly,
      }),
      actions: {
        fill: {
          argument: 'text',
          run: (value) =>
            (() => {
              if (props.readOnly) throw new Error('The field is read-only.')
              agentFill(control.value, value)
            })(),
        },
        clear: () =>
          (() => {
            if (props.readOnly) throw new Error('The field is read-only.')
            agentFill(control.value, '')
          })(),
      },
    })
    release3 = () => {
      ran()
    }
  }
  onMount(effect3)
  onCleanup(() => release3?.())
  return (
    <textarea
      class={styles.textarea}
      id={props.id}
      rows={props.rows}
      value={props.value ?? draft.value}
      placeholder={props.placeholder}
      name={props.name}
      maxlength={props.maxLength}
      disabled={props.disabled}
      readonly={props.readOnly}
      aria-label={props['aria-label']}
      aria-labelledby={props['aria-labelledby']}
      aria-describedby={props['aria-describedby']}
      aria-required={props['aria-required']}
      aria-invalid={props.invalid ? true : undefined}
      data-resize={resizing.value}
      data-autosize={props.autosize ? '' : undefined}
      data-invalid={props.invalid ? '' : undefined}
      data-disabled={props.disabled ? '' : undefined}
      data-readonly={props.readOnly ? '' : undefined}
      data-member="textarea"
      oninput={($event: InputEvent) => (
        (draft.value = control.value?.value ?? ''),
        props.autosize && control.value && fitTextarea(control.value),
        props.onChange?.(draft.value, $event)
      )}
      onblur={($event: FocusEvent) => props.onBlur?.($event)}
      onfocus={($event: FocusEvent) => props.onFocus?.($event)}
      onselect={($event: Event) => props.onSelect?.($event)}
      oncompositionstart={($event: CompositionEvent) => props.onCompositionStart?.($event)}
      oncompositionend={($event: CompositionEvent) => props.onCompositionEnd?.($event)}
      ref={control.attach}
    />
  )
}
